begin;
create function pg_temp.trainer_check(ok boolean,description text) returns void language plpgsql as $$begin if ok is not true then raise exception 'Trainer management: %',description;end if;end $$;
set local role service_role;
do $$
declare youth uuid; trainer uuid; target uuid; team uuid; another uuid; result jsonb; feed jsonb; data jsonb; v bigint; before_cash bigint;
begin
 select suite_user_id into youth from private.cashbook_accounts where username='schmo';
 select suite_user_id into trainer from private.cashbook_accounts where username='jentm';
 select id into target from public.social_people where slug='axel-schauble';
 select id into another from public.social_people where slug='simon-buhler';
 select id into team from public.social_teams where slug='u15-c1-junioren';
 before_cash:=private.cashbook_balance();
 perform pg_temp.trainer_check((select website_name='' from private.trainer_profiles where person_id=target),'normal public name follows person');
 perform pg_temp.trainer_check((select first_name='Noemi Sophie' and last_name='Friedrich' from private.trainer_profiles p join public.social_people s on s.id=p.person_id where s.slug='noemi-sophie-friedrich'),'full first and last name');
 result:=public.trainer_management_request(trainer,'{"action":"list"}');perform pg_temp.trainer_check(result->>'status'='403','ordinary trainer cannot read contacts');
 result:=public.trainer_management_request(youth,'{"action":"list"}');perform pg_temp.trainer_check(not result ? 'error' and jsonb_array_length(result->'people')>40,'youth leadership sees all existing trainers');
 perform pg_temp.trainer_check((select count(*)=4 from public.social_team_people a join public.social_teams t on t.id=a.team_id where t.slug='u6-spielgruppe' and a.staff_slot is not null),'all four U6 trainers retained');
 select version into v from private.trainer_profiles where person_id=target;
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_person','personId',target,'version',v,'firstName','Axel','lastName','Schäuble','birthDate','1980-02-14','email','private@example.test','phone','+49 123 4567','mobile','+49 999 888','street','Private Straße 1','postcode','78315','city','Radolfzell','notes','Geheime Notiz','qualification','C-Lizenz','active',true));
 perform pg_temp.trainer_check(not result ? 'error','contact save succeeds');
 feed:=public.website_trainers_feed();perform pg_temp.trainer_check(feed::text not like '%private@example.test%' and feed::text not like '%Private Straße%' and feed::text not like '%1980-02-14%' and feed::text not like '%Geheime Notiz%' and feed::text not like '%+49 999 888%','public feed never contains private contact fields');
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_photo','personId',target,'version',v,'photoPath',target::text||'/'||repeat('a',64)||'.jpg'));perform pg_temp.trainer_check(result->>'status'='409','stale photo cannot overwrite newer person');
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_photo','personId',target,'version',v+1,'photoPath',another::text||'/'||repeat('a',64)||'.jpg'));perform pg_temp.trainer_check(result->>'status'='400','cannot attach another person photo');
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_photo','personId',target,'version',v+1,'photoPath',target::text||'/'||repeat('a',64)||'.jpg'));perform pg_temp.trainer_check(not result ? 'error','photo path stored with revision');
 select trainer_version into v from public.social_teams where id=team;
 data:=jsonb_build_object('action','save_team','teamId',team,'version',v,'assignments',jsonb_build_array(jsonb_build_object('slot','trainer','personId',target,'websiteVisible',true),jsonb_build_object('slot','co1','personId',target,'websiteVisible',true)));
 result:=public.trainer_management_request(youth,data);perform pg_temp.trainer_check(result->>'status'='400','duplicate trainer rejected');
 data:=jsonb_build_object('action','save_team','teamId',team,'version',v,'assignments',jsonb_build_array(jsonb_build_object('slot','trainer','personId',another,'websiteVisible',true),jsonb_build_object('slot','co1','personId',target,'websiteVisible',false)));
 result:=public.trainer_management_request(youth,data);perform pg_temp.trainer_check(not result ? 'error','positions saved atomically');
 result:=public.trainer_management_request(youth,data);perform pg_temp.trainer_check(result->>'status'='409','stale team save rejected');
 feed:=public.website_trainers_feed();select value into feed from jsonb_array_elements(feed->'teams') where value->>'path'='jugend/u15-c1';
 perform pg_temp.trainer_check(jsonb_array_length(feed->'coaches')=1 and feed->'coaches'->0->>'name'='Simon Bühler' and feed->'coaches'->0->>'role'='Trainer','C1 homepage reflects current trainer; internal co-trainer excluded');
 perform pg_temp.trainer_check(exists(select 1 from public.social_team_people where team_id=team and person_id=another and role='Trainer'),'cashbook uses the same assignments');
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_team','teamId',team,'version',v+1,'assignments','[]'::jsonb));
 feed:=public.website_trainers_feed();select value into feed from jsonb_array_elements(feed->'teams') where value->>'path'='jugend/u15-c1';perform pg_temp.trainer_check(feed->'coaches'='[]'::jsonb,'empty authoritative team is included');
 select version into v from private.trainer_profiles where person_id=target;
 result:=public.trainer_management_request(youth,jsonb_build_object('action','save_person','personId',target,'version',v,'firstName','Axel','lastName','Schäuble','email','public@example.test','phone','+49 123 4567','publicEmail',true,'publicPhone',true,'active',true));
 select trainer_version into v from public.social_teams where id=team;
 perform public.trainer_management_request(youth,jsonb_build_object('action','save_team','teamId',team,'version',v,'assignments',jsonb_build_array(jsonb_build_object('slot','trainer','personId',target,'websiteVisible',true))));
 feed:=public.website_trainers_feed();perform pg_temp.trainer_check(feed::text like '%public@example.test%' and feed::text like '%+49 123 4567%','explicitly approved contacts published');
 update public.social_admins set is_blocked=true where user_id=youth;
 result:=public.trainer_management_request(youth,'{"action":"list"}');perform pg_temp.trainer_check(result->>'status'='403','freshly blocked user rejected');
 perform pg_temp.trainer_check(before_cash=private.cashbook_balance(),'trainer management cannot change cash balance');
 perform pg_temp.trainer_check((select count(*)>=6 from private.trainer_audit where actor=youth),'changes audited with actor and timestamp');
end $$;
reset role;
select pg_temp.trainer_check(not has_table_privilege('authenticated','private.trainer_profiles','SELECT') and not has_table_privilege('anon','private.trainer_profiles','SELECT'),'private contacts are inaccessible directly');
select pg_temp.trainer_check(not has_function_privilege('authenticated','public.trainer_management_request(uuid,jsonb)','EXECUTE') and not has_function_privilege('anon','public.website_trainers_feed()','EXECUTE'),'browser cannot bypass Edge/RPC authorization');
rollback;
